esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try transferring from this contract to some recipient
    function run(address to, uint256 value, address other) public payable {
        require(to != address(0)); // transfers to zero address are known to revert in C, avoid trivial always-revert
        require(other != to);
        // observe before-values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTo = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 beforeOther = c.balanceOf(other); if (__ESBMC_reverted()) return;

        bool didRevert;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterTo = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 afterOther = c.balanceOf(other); if (__ESBMC_reverted()) return;

        // General rule: if the transfer succeeded then totalSupply is unchanged and
        // only sender and recipient balances may have changed with conservation between them;
        // if it reverted then nothing observable (totalSupply and balances) changed.
        assert(
            didRevert
            ? (afterTotal == beforeTotal && afterSender == beforeSender && afterTo == beforeTo && afterOther == beforeOther)
            : (afterTotal == beforeTotal &&
               // sender decreased by exactly amount transferred OR stayed same if underflow prevented success
               (beforeSender - afterSender == afterTo - beforeTo) &&
               // other unrelated address unchanged
               afterOther == beforeOther)
        );
    }

    receive() external payable { }
}

