pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 value, address other) internal {
        vm.assume(to != address(0));
        vm.assume(other != to);
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeSender;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeSender = __r; } catch { return; }
        uint256 beforeTo;
        try c.balanceOf(to) returns (uint256 __r) { beforeTo = __r; } catch { return; }
        uint256 beforeOther;
        try c.balanceOf(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        bool didRevert;
        try c.transfer(to, value) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 afterSender;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterSender = __r; } catch { return; }
        uint256 afterTo;
        try c.balanceOf(to) returns (uint256 __r) { afterTo = __r; } catch { return; }
        uint256 afterOther;
        try c.balanceOf(other) returns (uint256 __r) { afterOther = __r; } catch { return; }
        assertTrue(didRevert
            ? (afterTotal == beforeTotal && afterSender == beforeSender && afterTo == beforeTo && afterOther == beforeOther)
            : (afterTotal == beforeTotal &&
               // sender decreased by exactly amount transferred OR stayed same if underflow prevented success
               (beforeSender - afterSender == afterTo - beforeTo) &&
               // other unrelated address unchanged
               afterOther == beforeOther));
    }

    function testFuzz_run(address to, uint256 value, address other) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, value, other);
    }

    receive() external payable { }
}
